import { request } from '@/admin/api/client';
import { type Settings } from '@/admin/api/settings';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import copy from '@/lib/copy-to-clipboard';
import { useMutation } from '@tanstack/react-query';
import { useStore } from '@tanstack/react-store';
import { __ } from '@wordpress/i18n';
import {
	CheckCircle,
	Copy,
	ExternalLink,
	Info,
	Loader2,
	XCircle,
} from 'lucide-react';
import { toast } from 'sonner';
import {
	paymentFormOptions,
	usePaymentFormContext,
} from './payment-form-context';

const PAYPAL_SUPPORTED_CURRENCIES = new Set([
	'AUD',
	'BRL',
	'CAD',
	'CNY',
	'CZK',
	'DKK',
	'EUR',
	'HKD',
	'HUF',
	'ILS',
	'JPY',
	'MYR',
	'MXN',
	'TWD',
	'NZD',
	'NOK',
	'PHP',
	'PLN',
	'GBP',
	'SGD',
	'SEK',
	'CHF',
	'THB',
	'USD',
]);

const PAYPAL_DEVELOPER_BASE = 'https://developer.paypal.com';

function ExternalHelpLink({
	href,
	children,
}: {
	href: string;
	children: string;
}) {
	return (
		<a
			href={href}
			target="_blank"
			rel="noopener noreferrer"
			className="inline-flex items-center gap-0.5 text-[12px] text-teal-600 hover:underline"
		>
			{children}
			<ExternalLink className="size-3" />
		</a>
	);
}

export default function PayPalSettingsSection() {
	const form = usePaymentFormContext(paymentFormOptions);
	const sandbox = useStore(form.store, (s) => s.values.paypal.sandbox);
	const env = sandbox ? 'sandbox' : 'live';
	const appsUrl = `${PAYPAL_DEVELOPER_BASE}/dashboard/applications/${env}`;
	const webhooksUrl = `${PAYPAL_DEVELOPER_BASE}/dashboard/webhooks/${env}`;

	const testConnection = useMutation({
		mutationFn: async () => {
			const {
				client_id,
				secret,
				sandbox: isSandbox,
			} = form.getFieldValue('paypal');
			if (!client_id || !secret) {
				throw new Error(__('Enter Client ID and Secret first.', 'allcoach'));
			}
			return request<{ success: boolean; message: string }>(
				'/paypal/test-connection',
				{
					method: 'POST',
					data: { client_id, secret, sandbox: isSandbox },
				},
			);
		},
		onError: (err) => {
			toast.error(
				err instanceof Error
					? err.message
					: __('Connection test failed.', 'allcoach'),
			);
		},
	});

	const handleCopyWebhookUrl = async () => {
		try {
			await copy(__ALLCOACH_ADMIN__.paypalWebhookUrl);
			toast.success(__('Webhook URL copied to clipboard.', 'allcoach'));
		} catch {
			toast.error(__('Failed to copy URL.', 'allcoach'));
		}
	};

	return (
		<div className="mt-3 overflow-hidden rounded-lg border border-gray-200">
			<div className="flex items-center justify-between px-5 py-4">
				<div>
					<p className="text-[13px] font-semibold text-gray-900">
						{__('PayPal', 'allcoach')}
					</p>
					<p className="text-[12px] text-gray-400">
						{__('Accept payments via PayPal.', 'allcoach')}
					</p>
				</div>
				<form.AppField name="paypal.enabled">
					{(field) => (
						<Switch
							checked={field.state.value}
							onCheckedChange={field.handleChange}
							className="cursor-pointer data-[state=checked]:!bg-teal-600"
						/>
					)}
				</form.AppField>
			</div>

			<form.Subscribe selector={(s) => s.values.paypal.enabled}>
				{(enabled) =>
					enabled && (
						<div className="space-y-4 border-t border-gray-100 bg-gray-50 px-5 py-4">
							{/* Currency warning */}
							<form.Subscribe selector={(s) => s.values.currency}>
								{(currency) => {
									if (
										!PAYPAL_SUPPORTED_CURRENCIES.has(currency.toUpperCase())
									) {
										return (
											<Alert className="flex items-center gap-3 border-amber-200 bg-amber-50 text-amber-900 [&>svg]:translate-y-0">
												<Info />
												<AlertDescription className="text-[12px] text-amber-700">
													{`${currency} `}
													{__(
														'is not supported by PayPal. Switch to a supported currency (USD, EUR, GBP…) or PayPal payments will fail at checkout.',
														'allcoach',
													)}
												</AlertDescription>
											</Alert>
										);
									}
								}}
							</form.Subscribe>

							<form.AppField name="paypal.title">
								{(field) => (
									<div>
										<Label className="mb-1.5 block text-[13px] font-medium text-gray-700">
											{__('Title', 'allcoach')}
										</Label>
										<Input
											placeholder="PayPal"
											value={field.state.value}
											onChange={(e) => field.handleChange(e.target.value)}
											onBlur={field.handleBlur}
											className="bg-white text-[13px]"
										/>
									</div>
								)}
							</form.AppField>

							<form.AppField name="paypal.description">
								{(field) => (
									<div>
										<Label className="mb-1.5 block text-[13px] font-medium text-gray-700">
											{__('Description', 'allcoach')}
										</Label>
										<Textarea
											placeholder={__(
												'Instructions shown to the client at checkout.',
												'allcoach',
											)}
											value={field.state.value}
											onChange={(e) => field.handleChange(e.target.value)}
											onBlur={field.handleBlur}
											rows={2}
											className="resize-none bg-white text-[13px]"
										/>
									</div>
								)}
							</form.AppField>

							{/* Sandbox toggle */}
							<form.AppField name="paypal.sandbox">
								{(field) => (
									<div className="flex items-center justify-between">
										<div>
											<Label className="block text-[13px] font-medium text-gray-700">
												{__('Sandbox mode', 'allcoach')}
											</Label>
											<p className="text-[12px] text-gray-400">
												{__('Use PayPal sandbox for testing.', 'allcoach')}{' '}
												<ExternalHelpLink
													href={`${PAYPAL_DEVELOPER_BASE}/tools/sandbox/`}
												>
													{__('Learn more', 'allcoach')}
												</ExternalHelpLink>
											</p>
										</div>
										<Switch
											checked={field.state.value}
											onCheckedChange={field.handleChange}
											className="cursor-pointer data-[state=checked]:!bg-teal-600"
										/>
									</div>
								)}
							</form.AppField>

							{/* API credentials */}
							<form.AppField name="paypal.client_id">
								{(field) => (
									<div>
										<div className="mb-1.5 flex items-center justify-between gap-2">
											<Label className="text-[13px] font-medium text-gray-700">
												{__('Client ID', 'allcoach')}
											</Label>
											<ExternalHelpLink href={appsUrl}>
												{__('Get API credentials', 'allcoach')}
											</ExternalHelpLink>
										</div>
										<Input
											placeholder={__('PayPal REST API client ID', 'allcoach')}
											value={field.state.value}
											onChange={(e) => field.handleChange(e.target.value)}
											onBlur={field.handleBlur}
											className="bg-white font-mono text-[13px]"
										/>
									</div>
								)}
							</form.AppField>

							<form.AppField name="paypal.secret">
								{(field) => (
									<div>
										<Label className="mb-1.5 block text-[13px] font-medium text-gray-700">
											{__('Secret', 'allcoach')}
										</Label>
										<Input
											type="password"
											placeholder={__('PayPal REST API secret', 'allcoach')}
											value={field.state.value}
											onChange={(e) => field.handleChange(e.target.value)}
											onBlur={field.handleBlur}
											className="bg-white font-mono text-[13px]"
										/>
									</div>
								)}
							</form.AppField>

							{/* Test connection */}
							<div className="flex items-center gap-3">
								<Button
									type="button"
									variant="outline"
									size="sm"
									disabled={testConnection.isPending}
									onClick={() => testConnection.mutate()}
									className="cursor-pointer text-[13px]"
								>
									{testConnection.isPending ? (
										<Loader2 className="size-3.5 animate-spin" />
									) : null}
									{__('Test Connection', 'allcoach')}
								</Button>

								{testConnection.isSuccess && (
									<span
										className={`flex items-center gap-1.5 text-[12px] font-medium ${
											testConnection.data.success
												? 'text-teal-600'
												: 'text-red-500'
										}`}
									>
										{testConnection.data.success ? (
											<CheckCircle className="size-3.5 shrink-0" />
										) : (
											<XCircle className="size-3.5 shrink-0" />
										)}
										{testConnection.data.message}
									</span>
								)}

								{testConnection.isError && (
									<span className="flex items-center gap-1.5 text-[12px] font-medium text-red-500">
										<XCircle className="size-3.5 shrink-0" />
										{testConnection.error instanceof Error
											? testConnection.error.message
											: __('Connection test failed.', 'allcoach')}
									</span>
								)}
							</div>

							{/* Webhook ID */}
							<form.AppField name="paypal.webhook_id">
								{(field) => (
									<div>
										<div className="mb-1.5 flex items-center justify-between gap-2">
											<Label className="text-[13px] font-medium text-gray-700">
												{__('Webhook ID', 'allcoach')}
											</Label>
											<ExternalHelpLink href={webhooksUrl}>
												{__('Create webhook in PayPal', 'allcoach')}
											</ExternalHelpLink>
										</div>
										<Input
											placeholder={__(
												'PayPal webhook ID for signature verification',
												'allcoach',
											)}
											value={field.state.value}
											onChange={(e) => field.handleChange(e.target.value)}
											onBlur={field.handleBlur}
											className="bg-white font-mono text-[13px]"
										/>
									</div>
								)}
							</form.AppField>

							{/* Webhook URL */}
							<div>
								<div className="mb-1.5 flex items-center justify-between gap-2">
									<Label className="text-[13px] font-medium text-gray-700">
										{__('Webhook URL', 'allcoach')}
									</Label>
									<ExternalHelpLink href={webhooksUrl}>
										{__('Add webhook in PayPal', 'allcoach')}
									</ExternalHelpLink>
								</div>
								<div className="flex gap-2">
									<Input
										value={__ALLCOACH_ADMIN__.paypalWebhookUrl}
										readOnly
										className="bg-white font-mono text-[13px]"
									/>
									<Button
										type="button"
										variant="outline"
										size="icon"
										className="shrink-0 cursor-pointer"
										aria-label={__('Copy PayPal webhook URL', 'allcoach')}
										onClick={handleCopyWebhookUrl}
									>
										<Copy className="size-4" />
									</Button>
								</div>
								<p className="mt-1 text-[12px] text-gray-400">
									{__(
										'Copy this URL, add it as a webhook in PayPal, then paste the webhook ID above.',
										'allcoach',
									)}
								</p>
							</div>

							<form.AppField name="paypal.payment_action">
								{(field) => (
									<div>
										<div className="mb-1.5 flex items-center justify-between gap-2">
											<Label className="text-[13px] font-medium text-gray-700">
												{__('Payment action', 'allcoach')}
											</Label>
											<ExternalHelpLink href="https://developer.paypal.com/docs/checkout/standard/integrate/#link-authorizeandcapturepayments">
												{__('Capture vs Authorize', 'allcoach')}
											</ExternalHelpLink>
										</div>
										<Select
											value={field.state.value}
											onValueChange={(v) =>
												field.handleChange(
													v as Settings['payment_paypal_payment_action'],
												)
											}
										>
											<SelectTrigger className="w-full bg-white text-[13px]">
												<SelectValue />
											</SelectTrigger>
											<SelectContent className="!z-[999999]">
												<SelectItem value="capture" className="text-[13px]">
													{__('Capture', 'allcoach')}
												</SelectItem>
												<SelectItem value="authorize" className="text-[13px]">
													{__('Authorize', 'allcoach')}
												</SelectItem>
											</SelectContent>
										</Select>
									</div>
								)}
							</form.AppField>

							<form.AppField name="paypal.shipping_preference">
								{(field) => (
									<div>
										<Label className="mb-1.5 block text-[13px] font-medium text-gray-700">
											{__('Shipping address', 'allcoach')}
										</Label>
										<Select
											value={field.state.value}
											onValueChange={(v) =>
												field.handleChange(
													v as Settings['payment_paypal_shipping_preference'],
												)
											}
										>
											<SelectTrigger className="w-full bg-white text-[13px]">
												<SelectValue />
											</SelectTrigger>
											<SelectContent className="!z-[999999]">
												<SelectItem value="no_shipping" className="text-[13px]">
													{__("Don't collect a shipping address", 'allcoach')}
												</SelectItem>
												<SelectItem
													value="get_from_file"
													className="text-[13px]"
												>
													{__(
														"Collect the buyer's PayPal shipping address",
														'allcoach',
													)}
												</SelectItem>
											</SelectContent>
										</Select>
									</div>
								)}
							</form.AppField>
						</div>
					)
				}
			</form.Subscribe>
		</div>
	);
}
