import { request } from './client';

export type Module = {
	id: string;
	name: string;
	description: string;
	version: string;
	/** Grouping bucket on the Add-ons page. */
	category: string;
	/** Whether activating this addon requires a valid Pro license. */
	pro: boolean;
	/** Non-license prerequisites (e.g. ['woocommerce']). */
	requires: string[];
	/** Dashicon slug or asset URL. */
	icon: string;
	thumbnail: string;
	docs_url: string;
	/** Admin SPA route for this addon's own settings screen ('' when none). */
	settings_route: string;
	/** 'core' (always-on) or 'addon' (toggleable). */
	type: 'core' | 'addon';
	toggleable: boolean;
	/** Default on/off before the user first toggled it. */
	default: boolean;
	enabled: boolean;
	/**
	 * True when a paid addon can't be activated here — no valid Pro license, or
	 * a Pro-only addon shown as a promo placeholder on the Free plugin.
	 */
	locked: boolean;
	/** Pricing page (UTM-tagged) the lock/upgrade affordances link to. */
	upgrade_url: string;
};

export const modulesApi = {
	list: () => request<{ modules: Module[] }>('/modules'),

	get: (id: string) => request<Module>(`/modules/${id}`),

	enable: (id: string) =>
		request<{ message: string; module: Module }>(`/modules/${id}/enable`, {
			method: 'POST',
		}),

	disable: (id: string) =>
		request<{ message: string; module: Module }>(`/modules/${id}/disable`, {
			method: 'POST',
		}),
};
