import { analyticsApi, type AnalyticsPreferences } from '@/admin/api/analytics';
import { useEffect, useState } from 'react';

/**
 * Per-user analytics dashboard preferences (KPI card metric picks, overview
 * chart focus) — stored server-side in user meta, not query params, so a
 * coach sees the same picks wherever they open the dashboard.
 *
 * Each caller fetches independently rather than sharing one cached instance:
 * this hook is used from both the Free and Pro bundles, and Pro's advanced
 * page can't share a React Context (e.g. a query cache) with components
 * compiled into the Free bundle's separate module instance.
 */
export function useAnalyticsPreferences() {
	const [preferences, setPreferences] = useState<AnalyticsPreferences>({});
	const [loaded, setLoaded] = useState(false);

	useEffect(() => {
		let active = true;
		analyticsApi
			.preferences()
			.then((p) => active && setPreferences(p ?? {}))
			.finally(() => active && setLoaded(true));
		return () => {
			active = false;
		};
	}, []);

	const savePreferences = (patch: AnalyticsPreferences) => {
		// Optimistic: the pick is local UI state, so apply it immediately and
		// persist in the background. A failed save shouldn't disrupt the view,
		// but log it so a broken endpoint isn't silently invisible.
		setPreferences((prev) => ({ ...prev, ...patch }));
		analyticsApi.updatePreferences(patch).catch((error) => {
			// eslint-disable-next-line no-console
			console.error('AllCoach: failed to save analytics preferences', error);
		});
	};

	return { preferences, loaded, savePreferences };
}
