import type { AnalyticsBreakdownSlice } from '@/admin/api/analytics';
import { analyticsQuery } from '@/admin/queries/analytics';
import { Card } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { useQuery } from '@tanstack/react-query';
import { getRouteApi } from '@tanstack/react-router';
import { applyFilters } from '@wordpress/hooks';
import { __ } from '@wordpress/i18n';
import { CalendarIcon, ChevronDown, Download, Lock, Printer } from 'lucide-react';
import type { ReactElement, ReactNode } from 'react';
import { useState } from 'react';
import BreakdownCharts from './breakdown-charts';
import KpiCards from './kpi-cards';
import OverviewChart from './overview-chart';
import { UnlockAnalyticsCard, UpgradeDialog } from './pro';

const routeApi = getRouteApi('/_app/analytics/');

/**
 * Extension seam: when AllCoach Pro's admin bundle is loaded, it registers a
 * filter that returns the full advanced dashboard, which replaces the Free
 * showcase entirely. Free ships no advanced code — only this seam + showcase.
 */
const ANALYTICS_PAGE_FILTER = 'allcoach.analytics.page';

/** Static sample data for the (blurred) Free showcase donuts — no real compute. */
const SAMPLE_BREAKDOWN: AnalyticsBreakdownSlice[] = [
	{ key: 's1', label: __('Paid', 'allcoach'), value: 8 },
	{ key: 's2', label: __('Pending', 'allcoach'), value: 3 },
	{ key: 's3', label: __('Cancelled', 'allcoach'), value: 1 },
];

/** A filter-bar control that looks real but opens the upgrade dialog. */
function LockedControl({
	icon,
	label,
	trailing = 'chevron',
	onClick,
}: {
	icon?: ReactNode;
	label: string;
	trailing?: 'chevron' | 'lock';
	onClick: () => void;
}) {
	return (
		<button
			type="button"
			onClick={onClick}
			className="inline-flex h-8 items-center gap-2 rounded-md px-3 text-sm font-normal text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
		>
			{icon}
			{label}
			{trailing === 'chevron' ? (
				<ChevronDown className="size-4 opacity-50" />
			) : (
				<Lock className="size-3.5 opacity-50" />
			)}
		</button>
	);
}

type UpgradeCopy = { title: string; description: string };

const UPGRADE_COPY = {
	advanced: {
		title: __('Unlock Advanced Analytics', 'allcoach'),
		description: __(
			'Filter by program, pick custom date ranges and switch granularity with AllCoach Pro.',
			'allcoach',
		),
	},
	export: {
		title: __('Unlock Export & Print', 'allcoach'),
		description: __(
			'Export your analytics as CSV and print detailed reports with AllCoach Pro.',
			'allcoach',
		),
	},
} satisfies Record<string, UpgradeCopy>;

export default function Analytics() {
	// If Pro provides an advanced page, render it and skip the Free showcase.
	const proPage = applyFilters(ANALYTICS_PAGE_FILTER, null) as ReactElement | null;
	if (proPage) {
		return proPage;
	}
	return <FreeAnalyticsShowcase />;
}

/** Free tier: real basic KPIs + basic overview, with locked/blurred advanced. */
function FreeAnalyticsShowcase() {
	const search = routeApi.useSearch();
	const [upgrade, setUpgrade] = useState<UpgradeCopy | null>(null);

	const { data, isLoading } = useQuery(
		analyticsQuery({
			from_date: search.from_date,
			to_date: search.to_date,
		}),
	);

	const openAdvanced = () => setUpgrade(UPGRADE_COPY.advanced);
	const openExport = () => setUpgrade(UPGRADE_COPY.export);

	// Sample data for the blurred showcase donuts (Free computes no breakdowns).
	const showcaseData = data
		? {
				...data,
				breakdowns: {
					orders_by_status: SAMPLE_BREAKDOWN,
					sessions_by_status: SAMPLE_BREAKDOWN,
					activity_completion: SAMPLE_BREAKDOWN,
					revenue_by_program: SAMPLE_BREAKDOWN,
				},
			}
		: data;

	return (
		<div className="mx-auto w-full max-w-[1400px] p-4 md:p-6">
			<Card className="gap-0 overflow-hidden border-0 p-0">
				{/* Filter bar — all controls locked in Free */}
				<div className="flex flex-wrap items-center justify-between gap-3 p-4">
					<div className="flex flex-wrap items-center gap-2">
						<LockedControl label={__('All Programs', 'allcoach')} onClick={openAdvanced} />
						<LockedControl
							icon={<CalendarIcon className="size-4 shrink-0" />}
							label={__('Last 30 days', 'allcoach')}
							onClick={openAdvanced}
						/>
						<LockedControl label={__('Day', 'allcoach')} onClick={openAdvanced} />
					</div>
					<div className="flex items-center gap-2">
						<LockedControl
							icon={<Download className="size-4" />}
							label={__('Export', 'allcoach')}
							trailing="lock"
							onClick={openExport}
						/>
						<LockedControl
							icon={<Printer className="size-4" />}
							label={__('Print', 'allcoach')}
							trailing="lock"
							onClick={openExport}
						/>
					</div>
				</div>

				{isLoading || !data || !showcaseData ? (
					<div className="p-4 md:p-6">
						<AnalyticsSkeleton />
					</div>
				) : (
					<>
						<div className="border-b border-gray-200">
							<KpiCards data={data} />
						</div>
						{/* Overview stays visible but muted; one card floats over it. */}
						<div className="relative border-b border-gray-200">
							<div className="pointer-events-none select-none blur-[2px]">
								<OverviewChart data={data} />
							</div>
							<div className="absolute inset-0 z-10 flex items-center justify-center bg-white/40">
								<UnlockAnalyticsCard />
							</div>
						</div>
						<div className="pointer-events-none select-none blur-[2px]">
							<BreakdownCharts data={showcaseData} />
						</div>
					</>
				)}
			</Card>

			<UpgradeDialog
				open={!!upgrade}
				onOpenChange={(open) => !open && setUpgrade(null)}
				title={upgrade?.title ?? ''}
				description={upgrade?.description ?? ''}
			/>
		</div>
	);
}

function AnalyticsSkeleton() {
	return (
		<div className="space-y-4">
			<Skeleton className="h-[116px] rounded-xl" />
			<Skeleton className="h-[400px] rounded-xl" />
			<div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
				{Array.from({ length: 3 }).map((_, i) => (
					<Skeleton key={i} className="h-[320px] rounded-xl" />
				))}
			</div>
		</div>
	);
}
