import { type Module } from '@/admin/api/modules';
import { GoogleIntegrationAlert } from '@/admin/components/google-integration-alert';
import { hooks } from '@/admin/hooks';
import { addonsQuery } from '@/admin/queries/addons';
import type { FileRoutesByFullPath } from '@/admin/routeTree.gen';
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { useQuery } from '@tanstack/react-query';
import { Link, Outlet, useLocation } from '@tanstack/react-router';
import { __ } from '@wordpress/i18n';
import {
	CalendarCheck,
	CalendarDays,
	CreditCard,
	Lock,
	Mail,
	Palette,
	ScrollText,
	SlidersHorizontal,
	Video,
} from 'lucide-react';

type SettingsPath = Exclude<
	Extract<keyof FileRoutesByFullPath, `/settings/${string}`>,
	'/settings/'
>;

export type SettingsNavItem = {
	label: string;
	icon: React.ComponentType<{ className?: string }>;
	to: SettingsPath;
};

const BASE_NAV_ITEMS: SettingsNavItem[] = [
	{
		label: __('Styling', 'allcoach'),
		icon: Palette,
		to: '/settings/styling',
	},
	{
		label: __('Availability', 'allcoach'),
		icon: CalendarDays,
		to: '/settings/availability',
	},
	{
		label: __('Emails', 'allcoach'),
		icon: Mail,
		to: '/settings/email',
	},
	{
		label: __('Payment', 'allcoach'),
		icon: CreditCard,
		to: '/settings/payment',
	},
	{
		label: __('Google Meet / Calendar', 'allcoach'),
		icon: CalendarCheck,
		to: '/settings/google-meet',
	},
	{
		label: __('Advanced', 'allcoach'),
		icon: SlidersHorizontal,
		to: '/settings/advanced',
	},
	{
		label: __('Logs', 'allcoach'),
		icon: ScrollText,
		to: '/settings/logs',
	},
];

// Lets other bundles (e.g. Pro) add their own tabs without editing this file.
const HOOK_SETTINGS_NAV_ITEMS = 'allcoach.admin.settingsNavItems';

// Dashicons are a 20px icon font; pin addon icons to the 16px (size-4) the
// lucide base-nav icons use so the sidebar stays visually aligned.
const DASHICON_STYLE = { fontSize: 16, width: 16, height: 16 } as const;

const Settings = () => {
	const pathname = useLocation().pathname;
	const navItems = hooks.applyFilters(
		HOOK_SETTINGS_NAV_ITEMS,
		BASE_NAV_ITEMS,
	) as SettingsNavItem[];
	const { data } = useQuery(addonsQuery());

	// Addon-contributed settings tabs, derived generically from the modules
	// payload: any addon that declares a settings route and is either enabled
	// (real tab) or locked (upsell). No per-addon wiring lives in this file.
	const addonNavItems = (data?.modules ?? []).filter(
		(m) =>
			m.type === 'addon' &&
			m.settings_route &&
			(m.enabled || m.locked) &&
			!navItems.some((n) => n.to === m.settings_route),
	);

	// Addon settings tabs slot in just before the "Advanced" system tab —
	// grouped with the feature settings above it rather than trailing the
	// Advanced/Logs/License system tabs.
	const advancedIndex = navItems.findIndex(
		(item) => item.to === '/settings/advanced',
	);
	const splitAt = advancedIndex === -1 ? navItems.length : advancedIndex;
	const featureItems = navItems.slice(0, splitAt);
	const systemItems = navItems.slice(splitAt);

	const renderNavLink = ({ label, icon: Icon, to }: SettingsNavItem) => (
		<Link
			key={to}
			to={to}
			type="button"
			className={`group flex shrink-0 cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-[13px] font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900 data-[status=active]:bg-teal-50 data-[status=active]:text-teal-700 lg:w-full lg:text-start`}
		>
			<Icon
				className={`size-4 shrink-0 text-gray-400 group-data-[status=active]:text-teal-600`}
			/>
			<span className="whitespace-nowrap">{label}</span>
		</Link>
	);

	// Enabled → a real tab; locked → an upsell that opens the (UTM-tagged)
	// pricing page. The addon's own dashicon keeps it consistent with its card.
	const renderAddonNavLink = (addon: Module) => {
		const iconClass = cn(
			'dashicons shrink-0',
			`dashicons-${addon.icon || 'admin-plugins'}`,
		);

		if (addon.locked) {
			return (
				<Tooltip key={addon.id}>
					<TooltipTrigger asChild>
						<a
							href={addon.upgrade_url || undefined}
							target={addon.upgrade_url ? '_blank' : undefined}
							rel={addon.upgrade_url ? 'noopener noreferrer' : undefined}
							className="flex shrink-0 cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-[13px] font-medium text-gray-400 select-none lg:w-full"
						>
							<span
								className={cn(iconClass, 'text-gray-300')}
								style={DASHICON_STYLE}
								aria-hidden
							/>
							<span className="whitespace-nowrap">{addon.name}</span>
							<Lock className="ms-auto size-3 shrink-0 text-gray-300" />
						</a>
					</TooltipTrigger>
					<TooltipContent>{__('Upgrade to unlock', 'allcoach')}</TooltipContent>
				</Tooltip>
			);
		}

		return (
			<Link
				key={addon.id}
				to={addon.settings_route}
				type="button"
				className="group flex shrink-0 cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-[13px] font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900 data-[status=active]:bg-teal-50 data-[status=active]:text-teal-700 lg:w-full lg:text-start"
			>
				<span
					className={cn(
						iconClass,
						'text-gray-400 group-data-[status=active]:text-teal-600',
					)}
					style={DASHICON_STYLE}
					aria-hidden
				/>
				<span className="whitespace-nowrap">{addon.name}</span>
			</Link>
		);
	};

	return (
		<div className="min-h-screen p-4 md:p-6">
			{pathname === '/settings/availability' && <GoogleIntegrationAlert />}
			<div className="mx-auto max-w-7xl">
				<div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:gap-5">
					{/* Sidebar */}
					<div className="rounded-xl bg-white lg:w-[280px] lg:shrink-0 lg:py-5">
						{/* Label – desktop only */}
						<p className="mb-3 hidden px-5 text-[11px] font-semibold tracking-widest text-gray-400 uppercase lg:block">
							{__('Global Settings', 'allcoach')}
						</p>

						{/* Nav – horizontal scroll on mobile, vertical on desktop */}
						<nav className="flex gap-1 overflow-x-auto px-3 py-3 lg:flex-col lg:gap-1.5 lg:py-0">
							{featureItems.map(renderNavLink)}

							{addonNavItems.map(renderAddonNavLink)}

							{systemItems.map(renderNavLink)}

							{/* Zoom – future integration, kept last until it ships. */}
							<div className="flex shrink-0 cursor-not-allowed items-center gap-2 rounded-lg px-3 py-2 text-[13px] font-medium text-gray-300 select-none lg:w-full">
								<Video className="size-4 shrink-0 text-gray-300" />
								<span className="whitespace-nowrap">Zoom</span>
								<span className="ms-1 rounded-full bg-gray-100 px-1.5 py-0.5 text-[10px] leading-none font-semibold tracking-wider text-gray-300 uppercase lg:ms-auto">
									{__('Coming soon', 'allcoach')}
								</span>
							</div>
						</nav>
					</div>

					{/* Content panel */}
					<div className="min-w-0 flex-1 overflow-hidden rounded-xl bg-white">
						<Outlet />
					</div>
				</div>
			</div>
		</div>
	);
};

export default Settings;
