import { settingsApi } from '@/admin/api/settings';
import { ColorField } from '@/admin/components/color-field';
import { settingsQuery } from '@/admin/queries/settings';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { Skeleton } from '@/components/ui/skeleton';
import { Spinner } from '@/components/ui/spinner';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { __ } from '@wordpress/i18n';
import { Palette } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';

const StylingSettings = () => {
	const queryClient = useQueryClient();

	const { data: settings, isLoading } = useQuery({
		...settingsQuery(),
		retry: false,
	});

	const [primaryColor, setPrimaryColor] = useState('');
	const [buttonColor, setButtonColor] = useState('');
	const [buttonHoverColor, setButtonHoverColor] = useState('');

	const initialized = useRef(false);
	useEffect(() => {
		if (!settings || initialized.current) return;
		initialized.current = true;
		setPrimaryColor(settings.primary_color ?? '');
		setButtonColor(settings.button_color ?? '');
		setButtonHoverColor(settings.button_hover_color ?? '');
	}, [settings]);

	const save = useMutation({
		mutationFn: () =>
			settingsApi.update({
				...settings,
				primary_color: primaryColor,
				button_color: buttonColor,
				button_hover_color: buttonHoverColor,
			}),
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ['settings'] });
			toast.success(__('Styling settings saved.', 'allcoach'));
		},
		onError: () => {
			toast.error(__('Failed to save settings.', 'allcoach'));
		},
	});

	return (
		<div className="flex flex-col">
			{/* Header */}
			<div className="flex items-center gap-2 border-b border-gray-100 px-5 py-5 md:px-8">
				<Palette className="size-4 text-teal-600" />
				<h2 className="text-[15px] font-semibold text-gray-900">
					{__('Styling', 'allcoach')}
				</h2>
			</div>

			{isLoading ? (
				<div className="space-y-6 px-5 py-6 md:px-8">
					<div>
						<Skeleton className="mb-1.5 h-4 w-32" />
						<Skeleton className="mb-5 h-3 w-64" />
						<Skeleton className="h-9 w-40" />
					</div>
					<Separator />
					<div>
						<Skeleton className="mb-1.5 h-4 w-32" />
						<Skeleton className="mb-5 h-3 w-64" />
						<div className="flex items-start gap-6">
							<Skeleton className="h-9 w-40" />
							<Skeleton className="h-9 w-40" />
						</div>
					</div>
				</div>
			) : (
				<>
					<div className="space-y-6 px-5 py-6 md:px-8">
						<div>
							<Label className="mb-1.5 block text-[13px] font-semibold text-gray-900">
								{__('Primary color', 'allcoach')}
							</Label>
							<p className="mb-5 text-[12px] text-gray-400">
								{__(
									'Choose a color to match your brand or site.',
									'allcoach',
								)}
							</p>
							<ColorField value={primaryColor} onChange={setPrimaryColor} />
						</div>

						<Separator />

						<div>
							<Label className="mb-1.5 block text-[13px] font-semibold text-gray-900">
								{__('Button color', 'allcoach')}
							</Label>
							<p className="mb-5 text-[12px] text-gray-400">
								{__(
									'Reflects on the primary buttons across your site.',
									'allcoach',
								)}
							</p>
							<div className="flex items-start gap-6">
								<ColorField
									label={__('Normal', 'allcoach')}
									value={buttonColor}
									onChange={setButtonColor}
								/>
								<ColorField
									label={__('Hover', 'allcoach')}
									value={buttonHoverColor}
									onChange={setButtonHoverColor}
								/>
							</div>
						</div>
					</div>

					{/* Footer */}
					<div className="flex justify-end gap-2 border-t border-gray-100 px-5 py-4 md:px-8">
						<Button
							type="button"
							size="sm"
							className="cursor-pointer bg-teal-600 text-[13px] hover:bg-teal-700"
							disabled={save.isPending}
							onClick={() => save.mutate()}
						>
							{save.isPending ? <Spinner className="size-3" /> : null}
							{__('Save', 'allcoach')}
						</Button>
					</div>
				</>
			)}
		</div>
	);
};

export default StylingSettings;
