import { request } from './client';

export type Settings = {
	// Styling
	primary_color: string;
	button_color: string;
	button_hover_color: string;
	// Email
	email_sender_name: string;
	email_sender_email: string;
	notify_welcome_client: boolean;
	notify_new_booking_confirmation: boolean;
	notify_new_booking_alert: boolean;
	notify_cancellation_notice: boolean;
	notify_24_hour_reminder: boolean;
	notify_order_confirmed: boolean;
	notify_order_cancelled: boolean;
	notify_session_booking_confirmation: boolean;
	notify_session_completed_follow_up: boolean;
	notify_session_cancelled_alert: boolean;
	// Payment
	currency: string;
	payment_offline_enabled: boolean;
	payment_offline_title: string;
	payment_offline_description: string;
	payment_paypal_enabled: boolean;
	payment_paypal_title: string;
	payment_paypal_description: string;
	payment_paypal_client_id: string;
	payment_paypal_secret: string;
	payment_paypal_sandbox: boolean;
	payment_paypal_webhook_id: string;
	payment_paypal_payment_action: 'capture' | 'authorize';
	payment_paypal_shipping_preference: 'no_shipping' | 'get_from_file';
	// Google
	google_client_id: string;
	google_client_secret: string;
	google_meet_enabled: boolean;
	// Advanced
	send_anonymous_usage_data: boolean;
	// Privacy / GDPR
	consent_required: boolean;
	consent_text: string;
	privacy_policy_version: string;
	delete_data_on_uninstall: boolean;
};

export const settingsApi = {
	get: () => request<Settings>('/settings'),
	update: (data: Partial<Settings>) =>
		request<Settings>('/settings', { method: 'PATCH', data }),
};
