/**
 * Build-time stub for `@tiptap/y-tiptap`, aliased in webpack.config.js.
 *
 * `@tiptap/extension-drag-handle` imports this package unconditionally, which
 * drags in yjs — and WordPress core already ships its own yjs inside
 * `wp-core-data`, so loading a second copy logs "Yjs was already imported".
 * AllCoach has no collaborative editing, so the real package is dead weight.
 *
 * Only the three symbols drag-handle imports are provided. Both position
 * helpers sit behind an `if (!ystate) return` guard that is always taken
 * without a registered collaboration plugin, so they throw rather than pretend
 * to work — if that assumption ever stops holding, it fails loudly here.
 */
import { PluginKey } from '@tiptap/pm/state';

export const ySyncPluginKey = new PluginKey('y-sync');

const unsupported = (name: string): never => {
	throw new Error(
		`${name} is unavailable: AllCoach stubs @tiptap/y-tiptap because it does not use collaborative editing.`,
	);
};

export function absolutePositionToRelativePosition(): never {
	return unsupported('absolutePositionToRelativePosition');
}

export function relativePositionToAbsolutePosition(): never {
	return unsupported('relativePositionToAbsolutePosition');
}
