import type { AnalyticsDashboard } from '@/admin/api/analytics';
import type { ChartConfig } from '@/components/ui/chart';
import {
	ChartContainer,
	ChartTooltip,
	ChartTooltipContent,
} from '@/components/ui/chart';
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select';
import { Skeleton } from '@/components/ui/skeleton';
import { cn } from '@/lib/utils';
import { __ } from '@wordpress/i18n';
import { BarChart3, LineChartIcon } from 'lucide-react';
import { useEffect, useState } from 'react';
import {
	Bar,
	CartesianGrid,
	ComposedChart,
	Line,
	XAxis,
	YAxis,
} from 'recharts';
import { useAnalyticsPreferences } from './use-analytics-preferences';
import { CHART_COLORS, formatBucketLabel, formatCurrency } from './utils';

type SeriesKey = 'revenue' | 'orders' | 'enrollments' | 'sessions';
type FocusKey = SeriesKey | 'all';
type ChartType = 'line' | 'bar';

const SERIES: {
	key: SeriesKey;
	label: string;
	color: string;
	axis: 'left' | 'right';
}[] = [
	{ key: 'revenue', label: __('Net Revenue', 'allcoach'), color: CHART_COLORS[0], axis: 'right' },
	{ key: 'orders', label: __('Orders', 'allcoach'), color: CHART_COLORS[1], axis: 'left' },
	{ key: 'enrollments', label: __('Enrollments', 'allcoach'), color: CHART_COLORS[2], axis: 'left' },
	{ key: 'sessions', label: __('Appointments', 'allcoach'), color: CHART_COLORS[3], axis: 'left' },
];

const chartConfig: ChartConfig = SERIES.reduce((acc, s) => {
	acc[s.key] = { label: s.label, color: s.color };
	return acc;
}, {} as ChartConfig);

const FOCUS_OPTIONS: { value: FocusKey; label: string }[] = [
	{ value: 'all', label: __('Overview', 'allcoach') },
	...SERIES.map((s) => ({ value: s.key, label: s.label })),
];

export default function OverviewChart({ data }: { data: AnalyticsDashboard }) {
	const { preferences, loaded, savePreferences } = useAnalyticsPreferences();
	const [chartType, setChartType] = useState<ChartType>('line');
	const [focus, setFocus] = useState<FocusKey>('all');
	const [active, setActive] = useState<Record<SeriesKey, boolean>>({
		revenue: true,
		orders: true,
		enrollments: true,
		sessions: true,
	});

	// Apply the server-stored focus pick once it's loaded.
	useEffect(() => {
		if (!loaded) return;
		const stored = preferences.overview_focus;
		if (stored && FOCUS_OPTIONS.some((o) => o.value === stored)) {
			setFocus(stored as FocusKey);
		}
	}, [loaded]);

	const setFocusAndSave = (value: FocusKey) => {
		setFocus(value);
		savePreferences({ overview_focus: value });
	};

	const groupBy = data.range.group_by;
	// "Focus" narrows to a single series; otherwise the legend toggles apply.
	const enabled =
		focus !== 'all'
			? SERIES.filter((s) => s.key === focus)
			: SERIES.filter((s) => active[s.key]);

	if (!loaded) {
		return (
			<section className="p-6">
				<Skeleton className="h-5 w-28" />
				<Skeleton className="mt-6 h-[320px] w-full" />
			</section>
		);
	}

	return (
		<section className="p-6">
			<div className="mb-4 flex flex-col items-start gap-3 md:flex-row md:items-center md:justify-between">
				{/* The card title itself is the metric selector (Everest-style). */}
				<Select value={focus} onValueChange={(v) => setFocusAndSave(v as FocusKey)}>
					<SelectTrigger className="h-auto w-fit gap-1.5 border-0 bg-transparent p-0 text-base font-semibold text-gray-900 shadow-none focus-visible:ring-0 dark:bg-transparent">
						<SelectValue />
					</SelectTrigger>
					<SelectContent align="start">
						{FOCUS_OPTIONS.map((o) => (
							<SelectItem key={o.value} value={o.value}>
								{o.label}
							</SelectItem>
						))}
					</SelectContent>
				</Select>

				<div className="flex flex-wrap items-center gap-x-4 gap-y-2">
					{/* Series legend / toggles */}
					<div className="flex flex-wrap items-center gap-3">
						{SERIES.map((s) => (
							<button
								key={s.key}
								type="button"
								onClick={() =>
									setActive((prev) => ({ ...prev, [s.key]: !prev[s.key] }))
								}
								className={cn(
									'inline-flex items-center gap-1.5 text-xs font-medium transition-opacity',
									active[s.key]
										? 'text-gray-700'
										: 'text-gray-400 line-through opacity-60',
								)}
							>
								<span
									className="size-2.5 rounded-[3px]"
									style={{ backgroundColor: s.color }}
								/>
								{s.label}
							</button>
						))}
					</div>

					{/* Chart type toggle */}
					<div className="flex items-center gap-0.5 rounded-md p-0.5">
						<button
							type="button"
							aria-label={__('Line chart', 'allcoach')}
							onClick={() => setChartType('line')}
							className={cn(
								'flex size-7 items-center justify-center rounded transition-colors',
								chartType === 'line'
									? 'bg-teal-50 text-teal-600'
									: 'text-gray-400 hover:text-gray-600',
							)}
						>
							<LineChartIcon className="size-4" />
						</button>
						<button
							type="button"
							aria-label={__('Bar chart', 'allcoach')}
							onClick={() => setChartType('bar')}
							className={cn(
								'flex size-7 items-center justify-center rounded transition-colors',
								chartType === 'bar'
									? 'bg-teal-50 text-teal-600'
									: 'text-gray-400 hover:text-gray-600',
							)}
						>
							<BarChart3 className="size-4" />
						</button>
					</div>
				</div>
			</div>
			<div>
				<ChartContainer
					config={chartConfig}
					className="aspect-auto h-[320px] w-full"
				>
					<ComposedChart data={data.timeseries} margin={{ left: 4, right: 4 }}>
						<CartesianGrid vertical={false} strokeDasharray="3 3" />
						<XAxis
							dataKey="date"
							tickLine={false}
							axisLine={false}
							tickMargin={8}
							minTickGap={24}
							tickFormatter={(v: string) => formatBucketLabel(v, groupBy)}
						/>
						<YAxis
							yAxisId="left"
							tickLine={false}
							axisLine={false}
							width={36}
							allowDecimals={false}
						/>
						<YAxis
							yAxisId="right"
							orientation="right"
							tickLine={false}
							axisLine={false}
							width={44}
						/>
						<ChartTooltip
							content={
								<ChartTooltipContent
									labelFormatter={(v) => formatBucketLabel(String(v), groupBy)}
									formatter={(value, name) => {
										const num = Number(value);
										const display =
											name === 'revenue'
												? formatCurrency(num, data.currency)
												: num.toLocaleString();
										return (
											<div className="flex w-full items-center justify-between gap-3">
												<span className="text-muted-foreground capitalize">
													{chartConfig[name as SeriesKey]?.label ?? name}
												</span>
												<span className="font-mono font-medium tabular-nums">
													{display}
												</span>
											</div>
										);
									}}
								/>
							}
						/>
						{enabled.map((s) =>
							chartType === 'line' ? (
								<Line
									key={s.key}
									yAxisId={s.axis}
									type="monotone"
									dataKey={s.key}
									stroke={s.color}
									strokeWidth={2}
									dot={false}
									isAnimationActive={false}
								/>
							) : (
								<Bar
									key={s.key}
									yAxisId={s.axis}
									dataKey={s.key}
									fill={s.color}
									radius={[3, 3, 0, 0]}
									isAnimationActive={false}
								/>
							),
						)}
					</ComposedChart>
				</ChartContainer>
			</div>
		</section>
	);
}
