import { dateI18n, getSettings } from '@wordpress/date';
import type { DateRange } from 'react-day-picker';

/** Parse a `YYYY-MM-DD` date-only string as a local calendar date (never UTC). */
export function parseDateOnly(dateStr: string): Date {
	const [y, m, d] = dateStr.split('-').map(Number);
	return new Date(y, m - 1, d);
}

/** Serialize a Date to `YYYY-MM-DD` using its local calendar fields (never toISOString/UTC). */
export function toDateStr(d: Date): string {
	const y = d.getFullYear();
	const m = String(d.getMonth() + 1).padStart(2, '0');
	const day = String(d.getDate()).padStart(2, '0');
	return `${y}-${m}-${day}`;
}

/**
 * Display a `YYYY-MM-DD` date-only value using the site's configured date
 * format, without dateI18n's timezone re-projection (a bare calendar date has
 * no instant to re-project — anchoring the parse at UTC and reading it back
 * at UTC makes the result immune to both the browser's and the site's
 * timezone settings).
 */
export function formatDateOnly(dateStr: string): string {
	return dateI18n(getSettings().formats.date, `${dateStr}T00:00:00Z`, 'UTC');
}

export function formatDateRange(range: DateRange): string {
	if (range.from && range.to)
		return `${formatDateOnly(toDateStr(range.from))} – ${formatDateOnly(toDateStr(range.to))}`;
	if (range.from) return formatDateOnly(toDateStr(range.from));
	return '';
}
