import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

const HEX_PATTERN = /^#[0-9a-f]{6}$/i;

type ColorFieldProps = {
	label?: string;
	description?: string;
	value: string;
	onChange: (hex: string) => void;
};

// Single color swatch (a transparent native color input overlaid on a
// visible circle, so one click opens the OS picker directly) + hex input,
// reused as-is for both a standalone field (Primary color) and, rendered
// twice side by side, for a color pair (Button color: Normal / Hover) — no
// separate "color pair" component needed.
export const ColorField = ({
	label,
	description,
	value,
	onChange,
}: ColorFieldProps) => {
	const isValidHex = HEX_PATTERN.test(value);
	const swatchColor = isValidHex ? value : '#ffffff';

	return (
		<div className="flex flex-col gap-1.5">
			{label ? (
				<Label className="text-[12px] font-medium text-gray-500">
					{label}
				</Label>
			) : null}
			<div className="flex items-center gap-2">
				<div className="relative size-8 shrink-0">
					<div
						className="pointer-events-none absolute inset-0 rounded-full border border-gray-200 shadow-sm"
						style={{ backgroundColor: swatchColor }}
					/>
					<input
						type="color"
						value={swatchColor}
						onChange={(e) => onChange(e.target.value)}
						aria-label={label || 'Pick a color'}
						className="absolute inset-0 size-8 cursor-pointer opacity-0"
					/>
				</div>
				<Input
					value={value}
					onChange={(e) => onChange(e.target.value)}
					maxLength={7}
					spellCheck={false}
					className="h-9 w-28 font-mono text-[13px] uppercase"
				/>
			</div>
			{description ? (
				<p className="text-[12px] text-gray-400">{description}</p>
			) : null}
		</div>
	);
};
