import { type Module, modulesApi } from '@/admin/api/modules';
import { addonsQuery } from '@/admin/queries/addons';
import { Skeleton } from '@/components/ui/skeleton';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { __ } from '@wordpress/i18n';
import { useState } from 'react';
import { toast } from 'sonner';
import AddonCard from './addon-card';

type AddonsResponse = { modules: Module[] };

export default function Addons() {
	const queryClient = useQueryClient();
	const { data, isLoading } = useQuery(addonsQuery());
	const [pendingId, setPendingId] = useState<string | null>(null);

	const toggle = useMutation({
		mutationFn: ({ id, next }: { id: string; next: boolean }) =>
			next ? modulesApi.enable(id) : modulesApi.disable(id),
		onMutate: async ({ id, next }) => {
			setPendingId(id);
			await queryClient.cancelQueries({ queryKey: ['addons'] });
			const prev = queryClient.getQueryData<AddonsResponse>(['addons']);
			// Optimistically flip the toggle.
			queryClient.setQueryData<AddonsResponse>(['addons'], (old) =>
				old
					? {
							modules: old.modules.map((m) =>
								m.id === id ? { ...m, enabled: next } : m,
							),
						}
					: old,
			);
			return { prev };
		},
		onError: (error, _vars, ctx) => {
			if (ctx?.prev) {
				queryClient.setQueryData(['addons'], ctx.prev);
			}
			const message =
				error instanceof Error ? error.message : __('Something went wrong.', 'allcoach');
			toast.error(message);
		},
		onSuccess: (res) => {
			toast.success(res.message);
		},
		onSettled: () => {
			setPendingId(null);
			queryClient.invalidateQueries({ queryKey: ['addons'] });
		},
	});

	// Core features aren't toggleable, so they don't belong on a page about
	// turning things on/off.
	const addons = (data?.modules ?? []).filter((m) => m.type === 'addon');

	return (
		<div className="min-h-screen">
			<div className="mx-auto w-full max-w-[1280px] px-4 py-6 md:px-10">
				{isLoading ? (
					<div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-3">
						{Array.from({ length: 3 }).map((_, i) => (
							<Skeleton key={i} className="h-[168px] rounded-sm" />
						))}
					</div>
				) : addons.length === 0 ? (
					<div className="rounded-sm border border-dashed border-border bg-card p-10 text-center text-sm text-muted-foreground">
						{__('No add-ons available yet.', 'allcoach')}
					</div>
				) : (
					<div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-3">
						{addons.map((addon) => (
							<AddonCard
								key={addon.id}
								addon={addon}
								pending={pendingId === addon.id}
								onToggle={(next) => toggle.mutate({ id: addon.id, next })}
							/>
						))}
					</div>
				)}
			</div>
		</div>
	);
}
