import { __ } from '@wordpress/i18n';

export type FieldType =
	| 'shortAnswer'
	| 'longAnswer'
	| 'multipleChoice'
	| 'checkbox'
	| 'date'
	| 'fileUpload';

export type ActivityField = {
	id: string;
	type: FieldType;
	label?: string;
	question?: string;
	options?: Array<{ id: string; label: string }>;
	required?: boolean;
};

export type EnrichedActivity = {
	id: number;
	title: string;
	sectionTitle: string;
	week: number;
	isCompleted: boolean;
	schema?: {
		version: string;
		content: Record<string, unknown>;
	};
};

