import { request, toQuery } from './client';

export type AnalyticsGroupBy = 'day' | 'week' | 'month';

export type AnalyticsParams = {
	from_date?: string;
	to_date?: string;
	group_by?: AnalyticsGroupBy;
	program_id?: number;
};

export type AnalyticsKpi = {
	value: number;
	previous: number;
	change_pct: number | null;
	/** Present on the revenue KPI only. */
	currency?: string;
};

export type AnalyticsTimeseriesPoint = {
	date: string;
	revenue: number;
	orders: number;
	enrollments: number;
	sessions: number;
};

export type AnalyticsBreakdownSlice = {
	key: string;
	label: string;
	value: number;
};

export type AnalyticsDashboard = {
	range: {
		from: string;
		to: string;
		group_by: AnalyticsGroupBy;
		program_id: number | null;
	};
	currency: string;
	kpis: {
		revenue: AnalyticsKpi;
		avg_order_revenue: AnalyticsKpi;
		orders: AnalyticsKpi;
		clients: AnalyticsKpi;
		enrollments: AnalyticsKpi;
		sessions: AnalyticsKpi;
	};
	timeseries: AnalyticsTimeseriesPoint[];
	breakdowns: {
		orders_by_status: AnalyticsBreakdownSlice[];
		sessions_by_status: AnalyticsBreakdownSlice[];
		activity_completion: AnalyticsBreakdownSlice[];
		revenue_by_program: AnalyticsBreakdownSlice[];
	};
};

/** Per-user dashboard preferences — persisted server-side, not per-browser. */
export type AnalyticsPreferences = {
	kpi_slots?: string[] | null;
	overview_focus?: string | null;
	breakdown_slots?: string[] | null;
};

export const analyticsApi = {
	dashboard: (params?: AnalyticsParams) =>
		request<AnalyticsDashboard>('/analytics' + toQuery(params)),
	preferences: () => request<AnalyticsPreferences>('/analytics/preferences'),
	updatePreferences: (patch: AnalyticsPreferences) =>
		request<AnalyticsPreferences>('/analytics/preferences', {
			method: 'POST',
			data: patch,
		}),
};
