import type { AnalyticsGroupBy } from '@/admin/api/analytics';
import { analyticsQuery } from '@/admin/queries/analytics';
import { programsQuery } from '@/admin/queries/programs';
import Analytics from '@/admin/pages/analytics/analytics';
import { parseDate, parseEnum, parsePositiveInt } from '@/lib/utils';
import { createFileRoute } from '@tanstack/react-router';

const GROUP_BY = ['day', 'week', 'month'] as const satisfies readonly AnalyticsGroupBy[];

export type AnalyticsSearch = {
	from_date: string | undefined;
	to_date: string | undefined;
	group_by: AnalyticsGroupBy;
	program_id: number | undefined;
};

export const Route = createFileRoute('/_app/analytics/')({
	validateSearch: (search): AnalyticsSearch => ({
		from_date: parseDate(search.from_date),
		to_date: parseDate(search.to_date),
		group_by: parseEnum<AnalyticsGroupBy>(search.group_by, GROUP_BY) || 'day',
		program_id: parsePositiveInt(search.program_id),
	}),

	loaderDeps: ({ search }) => search,

	loader: ({ context, deps }) =>
		Promise.all([
			context.queryClient.ensureQueryData(
				analyticsQuery({
					from_date: deps.from_date,
					to_date: deps.to_date,
					group_by: deps.group_by,
					program_id: deps.program_id,
				}),
			),
			context.queryClient.ensureQueryData(programsQuery({ per_page: 100 })),
		]),

	component: Analytics,
});
