import type { AnalyticsParams } from '@/admin/api/analytics';
import { analyticsApi } from '@/admin/api/analytics';
import { keepPreviousData, queryOptions } from '@tanstack/react-query';

export type { AnalyticsParams };

export const analyticsQuery = (params?: AnalyticsParams) =>
	queryOptions({
		queryKey: ['analytics', params ?? {}] as const,
		queryFn: () => analyticsApi.dashboard(params),
		placeholderData: keepPreviousData,
		staleTime: 60_000,
		gcTime: 5 * 60_000,
	});
