import { createFileRoute, redirect } from '@tanstack/react-router';

export const Route = createFileRoute('/')({
	beforeLoad: () => {
		throw redirect({
			to: '/analytics',
			search: {
				from_date: undefined,
				to_date: undefined,
				group_by: 'day',
				program_id: undefined,
			},
		});
	},
});
