/**
 * Two-click range picker: unless `committed` is itself half-open, the first
 * click starts a fresh range and the second completes it, swapping if the second
 * click is earlier. `onComplete` fires only once both ends are picked, so callers
 * commit one filter change instead of one per click.
 *
 * The unfinished range is deliberately held here rather than by the caller, and
 * discarded whenever `open` goes false, so an abandoned half-selection cannot
 * anchor the next one. Pass the same state that controls the surrounding
 * popover — relying on unmount alone is not enough, since an exit animation
 * keeps this instance alive long enough for a fast reopen to reuse it.
 */
function RangeCalendar({
  committed,
  onComplete,
  open,
  ...props
}: {
  committed: DateRange | undefined
  onComplete: (range: { from: Date; to: Date }) => void
  open?: boolean
  numberOfMonths?: number
  autoFocus?: boolean
  className?: string
  disabled?: React.ComponentProps<typeof DayPicker>["disabled"]
}) {
  const [pending, setPending] = React.useState<DateRange | undefined>()

  React.useEffect(() => {
    if (open === false) setPending(undefined)
  }, [open])

  return (
    <Calendar
      mode="range"
      resetOnSelect
      selected={pending ?? committed}
      onSelect={(next, triggerDate) => {
        if (next?.from && next?.to) {
          setPending(undefined)
          onComplete({ from: next.from, to: next.to })
          return
        }
        // The library returns undefined when re-clicking the only day of a
        // single-day range; restart from that day rather than ignoring the click.
        setPending(next ?? { from: triggerDate, to: undefined })
      }}
      {...props}
    />
  )
}

export { Calendar, RangeCalendar }
