import type { AnalyticsDashboard } from '@/admin/api/analytics';
import type { ChartConfig } from '@/components/ui/chart';
import { ChartContainer } from '@/components/ui/chart';
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select';
import { __ } from '@wordpress/i18n';
import { useEffect, useState } from 'react';
import { Cell, Label, Pie, PieChart } from 'recharts';
import { useAnalyticsPreferences } from './use-analytics-preferences';
import { CHART_COLORS as PALETTE, formatCurrency, formatNumber } from './utils';

type BreakdownKey = keyof AnalyticsDashboard['breakdowns'];

const BREAKDOWNS: { key: BreakdownKey; title: string }[] = [
	{ key: 'orders_by_status', title: __('Orders by status', 'allcoach') },
	{ key: 'sessions_by_status', title: __('Appointments by status', 'allcoach') },
	{ key: 'activity_completion', title: __('Activity completion', 'allcoach') },
	{ key: 'revenue_by_program', title: __('Revenue by program', 'allcoach') },
];

const BREAKDOWN_KEYS = BREAKDOWNS.map((b) => b.key);
const DEFAULT_BREAKDOWN_SLOTS: BreakdownKey[] = [
	'orders_by_status',
	'sessions_by_status',
	'activity_completion',
];

/** Revenue breakdowns are currency amounts; the rest are plain counts. */
const CURRENCY_BREAKDOWNS: BreakdownKey[] = ['revenue_by_program'];

function Donut({
	selected,
	onSelect,
	data,
}: {
	selected: BreakdownKey;
	onSelect: (k: BreakdownKey) => void;
	data: AnalyticsDashboard;
}) {
	const slices = data.breakdowns[selected];
	const total = slices.reduce((sum, s) => sum + s.value, 0);
	const formatValue = (value: number) =>
		CURRENCY_BREAKDOWNS.includes(selected)
			? formatCurrency(value, data.currency)
			: formatNumber(value);

	const config: ChartConfig = slices.reduce((acc, s, i) => {
		acc[s.key] = { label: s.label, color: PALETTE[i % PALETTE.length] };
		return acc;
	}, {} as ChartConfig);

	return (
		<div className="p-6">
			<div className="mb-4">
				<Select value={selected} onValueChange={(v) => onSelect(v as BreakdownKey)}>
					<SelectTrigger className="h-auto w-fit gap-1 border-0 bg-transparent p-0 text-base font-semibold text-gray-900 shadow-none focus-visible:ring-0 dark:bg-transparent">
						<SelectValue />
					</SelectTrigger>
					<SelectContent align="start">
						{BREAKDOWNS.map((b) => (
							<SelectItem key={b.key} value={b.key}>
								{b.title}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			</div>
			<div>
				{total === 0 ? (
					<div className="flex h-[220px] items-center justify-center text-sm text-gray-400">
						{__('No data for this period', 'allcoach')}
					</div>
				) : (
					<>
						<ChartContainer
							config={config}
							className="mx-auto aspect-square h-[200px]"
						>
							<PieChart>
								<Pie
									data={slices}
									dataKey="value"
									nameKey="label"
									innerRadius={58}
									outerRadius={82}
									strokeWidth={2}
									isAnimationActive={false}
								>
									{slices.map((s, i) => (
										<Cell key={s.key} fill={PALETTE[i % PALETTE.length]} />
									))}
									<Label
										content={({ viewBox }) => {
											if (!viewBox || !('cx' in viewBox)) return null;
											const { cx, cy } = viewBox as { cx: number; cy: number };
											return (
												<text x={cx} y={cy} textAnchor="middle">
													<tspan
														x={cx}
														y={cy - 4}
														className="fill-gray-900 text-xl font-semibold"
													>
														{formatValue(total)}
													</tspan>
													<tspan
														x={cx}
														y={cy + 16}
														className="fill-gray-400 text-xs"
													>
														{__('Total', 'allcoach')}
													</tspan>
												</text>
											);
										}}
									/>
								</Pie>
							</PieChart>
						</ChartContainer>
						<ul className="mt-3 space-y-1.5">
							{slices.map((s, i) => (
								<li
									key={s.key}
									className="flex items-center justify-between text-sm"
								>
									<span className="flex items-center gap-2 text-gray-600">
										<span
											className="size-2.5 rounded-full"
											style={{ backgroundColor: PALETTE[i % PALETTE.length] }}
										/>
										{s.label}
									</span>
									<span className="font-medium text-gray-900">
										{formatValue(s.value)}
									</span>
								</li>
							))}
						</ul>
					</>
				)}
			</div>
		</div>
	);
}

export default function BreakdownCharts({ data }: { data: AnalyticsDashboard }) {
	// Three donut slots (matching the 3-column grid); every breakdown, including
	// revenue_by_program, is selectable within each slot's dropdown. Selections
	// persist server-side per user (same mechanism as the KPI card slots).
	const { preferences, loaded, savePreferences } = useAnalyticsPreferences();
	const [slots, setSlots] = useState<BreakdownKey[]>(DEFAULT_BREAKDOWN_SLOTS);

	// Apply the server-stored slot picks once they've loaded.
	useEffect(() => {
		if (!loaded) return;
		const stored = preferences.breakdown_slots;
		if (
			stored?.length === DEFAULT_BREAKDOWN_SLOTS.length &&
			stored.every((k) => BREAKDOWN_KEYS.includes(k as BreakdownKey))
		) {
			setSlots(stored as BreakdownKey[]);
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [loaded]);

	const setSlot = (index: number, key: BreakdownKey) => {
		setSlots((prev) => {
			const next = prev.map((k, i) => (i === index ? key : k));
			savePreferences({ breakdown_slots: next });
			return next;
		});
	};

	return (
		<div className="grid grid-cols-1 divide-y divide-gray-200 lg:grid-cols-3 lg:divide-x lg:divide-y-0">
			{slots.map((key, i) => (
				<Donut
					key={i}
					selected={key}
					onSelect={(k) => setSlot(i, k)}
					data={data}
				/>
			))}
		</div>
	);
}
