import { type Settings } from '@/admin/api/settings';
import {
	createFormHook,
	createFormHookContexts,
	formOptions,
} from '@tanstack/react-form';

export type PaymentFormValues = {
	currency: string;
	offline_payment: {
		enabled: boolean;
		title: string;
		description: string;
	};
	paypal: {
		enabled: boolean;
		title: string;
		description: string;
		client_id: string;
		secret: string;
		sandbox: boolean;
		webhook_id: string;
		payment_action: Settings['payment_paypal_payment_action'];
		shipping_preference: Settings['payment_paypal_shipping_preference'];
	};
};

export const PAYMENT_FORM_DEFAULTS: PaymentFormValues = {
	currency: 'USD',
	offline_payment: {
		enabled: true,
		title: 'Pay in person',
		description: 'Pay at the time of your session.',
	},
	paypal: {
		enabled: false,
		title: 'PayPal',
		description: 'Pay securely via PayPal.',
		client_id: '',
		secret: '',
		sandbox: true,
		webhook_id: '',
		payment_action: 'capture',
		shipping_preference: 'no_shipping',
	},
};

const normalizeBoolean = (value: unknown, fallback: boolean) => {
	if (typeof value === 'boolean') return value;
	if (typeof value === 'number') return value !== 0;
	if (typeof value === 'string') {
		if (value === '1' || value.toLowerCase() === 'true') return true;
		if (value === '0' || value.toLowerCase() === 'false') return false;
	}
	return fallback;
};

export const settingsToPaymentFormValues = (
	settings: Settings,
): PaymentFormValues => ({
	currency: settings.currency ?? PAYMENT_FORM_DEFAULTS.currency,
	offline_payment: {
		enabled: normalizeBoolean(
			settings.payment_offline_enabled,
			PAYMENT_FORM_DEFAULTS.offline_payment.enabled,
		),
		title:
			settings.payment_offline_title ??
			PAYMENT_FORM_DEFAULTS.offline_payment.title,
		description:
			settings.payment_offline_description ??
			PAYMENT_FORM_DEFAULTS.offline_payment.description,
	},
	paypal: {
		enabled: normalizeBoolean(
			settings.payment_paypal_enabled,
			PAYMENT_FORM_DEFAULTS.paypal.enabled,
		),
		title: settings.payment_paypal_title ?? PAYMENT_FORM_DEFAULTS.paypal.title,
		description:
			settings.payment_paypal_description ??
			PAYMENT_FORM_DEFAULTS.paypal.description,
		client_id:
			settings.payment_paypal_client_id ??
			PAYMENT_FORM_DEFAULTS.paypal.client_id,
		secret:
			settings.payment_paypal_secret ?? PAYMENT_FORM_DEFAULTS.paypal.secret,
		sandbox: normalizeBoolean(
			settings.payment_paypal_sandbox,
			PAYMENT_FORM_DEFAULTS.paypal.sandbox,
		),
		webhook_id:
			settings.payment_paypal_webhook_id ??
			PAYMENT_FORM_DEFAULTS.paypal.webhook_id,
		payment_action:
			settings.payment_paypal_payment_action ??
			PAYMENT_FORM_DEFAULTS.paypal.payment_action,
		shipping_preference:
			settings.payment_paypal_shipping_preference ??
			PAYMENT_FORM_DEFAULTS.paypal.shipping_preference,
	},
});

export const paymentFormOptions = formOptions({
	defaultValues: PAYMENT_FORM_DEFAULTS,
});

export const { fieldContext, formContext, useFieldContext } =
	createFormHookContexts();

export const {
	useAppForm: usePaymentForm,
	useTypedAppFormContext: usePaymentFormContext,
} = createFormHook({
	fieldContext,
	formContext,
	fieldComponents: {},
	formComponents: {},
});
