import type { Module } from '@/admin/api/modules';
import { Switch } from '@/components/ui/switch';
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { Link } from '@tanstack/react-router';
import { __, sprintf } from '@wordpress/i18n';
import { ExternalLink, Lock, Settings } from 'lucide-react';

// Tinted outline pill: 6%-opacity bg, matching border + text color.
const PILL_CLASSES =
	'inline-flex w-fit shrink-0 items-center rounded border px-2 py-0.5 text-xs whitespace-nowrap';
const PILL_NEUTRAL = 'border-slate-500 text-slate-500 bg-slate-500/[0.06]';
const PILL_PRO = 'border-primary text-primary bg-primary/[0.06]';

export default function AddonCard({
	addon,
	pending,
	onToggle,
}: {
	addon: Module;
	pending: boolean;
	onToggle: (next: boolean) => void;
}) {
	const hasUnmetRequirement = addon.requires.length > 0;
	const settingsRoute =
		addon.enabled && addon.settings_route ? addon.settings_route : undefined;

	// Trying to enable a locked addon sends the user to the pricing page in a
	// new tab instead — the URL already carries the addon's UTM campaign tag.
	const openUpgrade = () => {
		if (addon.upgrade_url) {
			window.open(addon.upgrade_url, '_blank', 'noopener,noreferrer');
		}
	};

	return (
		<div className="flex flex-col rounded-sm border border-slate-200 bg-white px-6 py-3">
			<div className="flex items-start justify-between gap-6">
				<div className="flex items-center gap-2">
					<span className="flex size-10 shrink-0 items-center justify-center rounded-sm bg-primary/10 text-primary">
						<span
							className={cn('dashicons', `dashicons-${addon.icon || 'admin-plugins'}`)}
							aria-hidden
						/>
					</span>
					<h3 className="text-base font-semibold text-foreground">{addon.name}</h3>
				</div>

				{addon.pro ? (
					<span className={cn(PILL_CLASSES, PILL_PRO)}>{__('Pro', 'allcoach')}</span>
				) : (
					<span className={cn(PILL_CLASSES, PILL_NEUTRAL)}>
						{__('Free', 'allcoach')}
					</span>
				)}
			</div>

			<p className="mt-3 line-clamp-2 flex-1 text-sm text-muted-foreground">
				{addon.description}
			</p>

			<div className="mt-3 flex items-center gap-3 border-t border-slate-100 pt-3">
				{addon.docs_url && (
					<a
						href={addon.docs_url}
						target="_blank"
						rel="noopener noreferrer"
						className="inline-flex items-center gap-1 text-xs font-medium text-muted-foreground hover:text-foreground"
					>
						{__('Docs', 'allcoach')}
						<ExternalLink className="size-3" />
					</a>
				)}

				<div className="ml-auto flex items-center gap-2">
					{settingsRoute && (
						<Tooltip>
							<TooltipTrigger asChild>
								<Link
									to={settingsRoute}
									className="flex size-6 items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground"
									aria-label={__('Settings', 'allcoach')}
								>
									<Settings className="size-3.5" />
								</Link>
							</TooltipTrigger>
							<TooltipContent>{__('Settings', 'allcoach')}</TooltipContent>
						</Tooltip>
					)}

					{/* A missing plugin dependency replaces the toggle entirely — nothing to switch on yet. */}
					{hasUnmetRequirement ? (
						<span className={cn(PILL_CLASSES, 'border-red-300 text-red-400 bg-red-50')}>
							{sprintf(
								/* translators: %s: comma-separated list of required plugins/features */
								__('Requires %s', 'allcoach'),
								addon.requires.join(', '),
							)}
						</span>
					) : addon.locked ? (
						<Tooltip>
							<TooltipTrigger asChild>
								<button
									type="button"
									onClick={openUpgrade}
									aria-label={__('Upgrade to unlock', 'allcoach')}
									className="inline-flex cursor-pointer items-center gap-1.5"
								>
									{/* Presentational off-switch (matches the disabled Switch look)
									    so the real control isn't nested inside this button. */}
									<span
										className="inline-flex h-[1.15rem] w-8 shrink-0 items-center rounded-full border border-transparent bg-input opacity-50 shadow-xs"
										aria-hidden
									>
										<span className="block size-4 rounded-full bg-background" />
									</span>
									<Lock className="size-3.5 text-muted-foreground" />
								</button>
							</TooltipTrigger>
							<TooltipContent>
								{__('Upgrade to unlock', 'allcoach')}
							</TooltipContent>
						</Tooltip>
					) : (
						<Switch
							checked={addon.enabled}
							disabled={pending}
							onCheckedChange={onToggle}
							aria-label={addon.name}
						/>
					)}
				</div>
			</div>
		</div>
	);
}
