import type {
	AnalyticsDashboard,
	AnalyticsGroupBy,
} from '@/admin/api/analytics';
import { __ } from '@wordpress/i18n';
import { format, parseISO } from 'date-fns';

export const GROUP_BY_OPTIONS: { value: AnalyticsGroupBy; label: string }[] = [
	{ value: 'day', label: __('Day', 'allcoach') },
	{ value: 'week', label: __('Week', 'allcoach') },
	{ value: 'month', label: __('Month', 'allcoach') },
];

/**
 * On-brand chart palette — shades of AllCoach teal only (no borrowed hues),
 * ordered dark → light so adjacent series stay distinguishable.
 */
export const CHART_COLORS = [
	'#0f766e', // teal-700
	'#0d9488', // teal-600
	'#14b8a6', // teal-500
	'#2dd4bf', // teal-400
	'#5eead4', // teal-300
];

/** "Jun 6, 2026 – Jul 6, 2026" style label for the date-range button. */
export function formatRangeLabel(from?: string, to?: string): string {
	if (!from) return __('Pick a date range', 'allcoach');
	const f = format(parseISO(from), 'MMM d, yyyy');
	if (!to) return f;
	return `${f} – ${format(parseISO(to), 'MMM d, yyyy')}`;
}

export function formatCurrency(value: number, currency: string): string {
	try {
		return new Intl.NumberFormat(undefined, {
			style: 'currency',
			currency,
			maximumFractionDigits: 2,
		}).format(value);
	} catch {
		return `${currency} ${value.toFixed(2)}`;
	}
}

export function formatNumber(value: number): string {
	return new Intl.NumberFormat().format(value);
}

/** Human axis/tooltip label for a bucket date, adapted to granularity. */
export function formatBucketLabel(
	date: string,
	groupBy: AnalyticsGroupBy,
): string {
	const d = parseISO(date);
	if (groupBy === 'month') return format(d, 'MMM yyyy');
	return format(d, 'MMM d');
}

export function formatChangePct(change: number | null): {
	text: string;
	direction: 'up' | 'down' | 'flat';
} {
	if (change === null || change === 0) {
		return { text: '0.0%', direction: 'flat' };
	}
	const direction = change > 0 ? 'up' : 'down';
	return { text: `${Math.abs(change).toFixed(1)}%`, direction };
}

/** Builds a CSV of the time-series and triggers a client-side download. */
export function exportDashboardCsv(data: AnalyticsDashboard): void {
	const header = [
		__('Date', 'allcoach'),
		__('Net Revenue', 'allcoach'),
		__('Orders', 'allcoach'),
		__('Enrollments', 'allcoach'),
		__('Appointments', 'allcoach'),
	];

	const rows = data.timeseries.map((p) => [
		p.date,
		String(p.revenue),
		String(p.orders),
		String(p.enrollments),
		String(p.sessions),
	]);

	const escape = (v: string) =>
		/[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;

	const csv = [header, ...rows]
		.map((row) => row.map(escape).join(','))
		.join('\n');

	const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
	const url = URL.createObjectURL(blob);
	const link = document.createElement('a');
	link.href = url;
	link.download = `allcoach-analytics-${data.range.from}_to_${data.range.to}.csv`;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
}
