import { hooks } from '@/admin/hooks';

export const HOOK_BEFORE_GATED_ACTION = 'allcoach.admin.beforeGatedAction';

/**
 * Lets other bundles (e.g. Pro) block a gated action - showing their own UI
 * (a license modal, an upsell, etc.) - before it runs. Always allows by
 * default, so Free behaves exactly the same when nothing hooks the filter.
 */
export function canPerformGatedAction(featureKey: string): boolean {
	return hooks.applyFilters(
		HOOK_BEFORE_GATED_ACTION,
		true,
		featureKey,
	) as boolean;
}
