import { settingsApi } from '@/admin/api/settings';
import { settingsQuery } from '@/admin/queries/settings';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Skeleton } from '@/components/ui/skeleton';
import { Spinner } from '@/components/ui/spinner';
import { Switch } from '@/components/ui/switch';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { __ } from '@wordpress/i18n';
import { AlertTriangle, SlidersHorizontal } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';

const AdvancedSettings = () => {
	const queryClient = useQueryClient();

	const { data: settings, isLoading } = useQuery({
		...settingsQuery(),
		retry: false,
	});

	const [sendUsageData, setSendUsageData] = useState(false);
	const [consentRequired, setConsentRequired] = useState(true);
	const [consentText, setConsentText] = useState('');
	const [policyVersion, setPolicyVersion] = useState('');
	const [deleteDataOnUninstall, setDeleteDataOnUninstall] = useState(false);

	const initialized = useRef(false);
	useEffect(() => {
		if (!settings || initialized.current) return;
		initialized.current = true;
		setSendUsageData(settings.send_anonymous_usage_data ?? false);
		setConsentRequired(settings.consent_required ?? true);
		setConsentText(settings.consent_text ?? '');
		setPolicyVersion(settings.privacy_policy_version ?? '');
		setDeleteDataOnUninstall(settings.delete_data_on_uninstall ?? false);
	}, [settings]);

	const save = useMutation({
		mutationFn: () =>
			settingsApi.update({
				...settings,
				send_anonymous_usage_data: sendUsageData,
				consent_required: consentRequired,
				consent_text: consentText,
				privacy_policy_version: policyVersion,
				delete_data_on_uninstall: deleteDataOnUninstall,
			}),
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ['settings'] });
			toast.success(__('Advanced settings saved.', 'allcoach'));
		},
		onError: () => {
			toast.error(__('Failed to save settings.', 'allcoach'));
		},
	});

	return (
		<div className="flex flex-col">
			{/* Header */}
			<div className="flex items-center gap-2 border-b border-gray-100 px-5 py-5 md:px-8">
				<SlidersHorizontal className="size-4 text-teal-600" />
				<h2 className="text-[15px] font-semibold text-gray-900">
					{__('Advanced', 'allcoach')}
				</h2>
			</div>

			{isLoading ? (
				<div className="px-5 py-6 md:px-8">
					<div className="overflow-hidden rounded-lg border border-gray-200">
						<div className="flex items-center justify-between px-5 py-4">
							<div>
								<Skeleton className="mb-1 h-4 w-56" />
								<Skeleton className="h-3 w-80" />
							</div>
							<Skeleton className="h-5 w-9 shrink-0 rounded-full" />
						</div>
					</div>
				</div>
			) : (
				<>
					<div className="px-5 py-6 md:px-8">
						<div className="overflow-hidden rounded-lg border border-gray-200">
							<div className="flex items-center justify-between gap-4 px-5 py-4">
								<div>
									<p className="text-[13px] font-medium text-gray-800">
										{__('Send anonymous usage data', 'allcoach')}
									</p>
									<p className="mt-0.5 text-[12px] text-gray-400">
										{__(
											'Help improve the plugin by sharing anonymous usage statistics. No personal data is collected and data is never shared with third parties.',
											'allcoach',
										)}
									</p>
								</div>
								<Switch
									checked={sendUsageData}
									onCheckedChange={setSendUsageData}
									className="shrink-0 cursor-pointer data-[state=checked]:!bg-teal-600"
								/>
							</div>
						</div>
					</div>

					{/* Privacy / GDPR */}
					<div className="px-5 pb-6 md:px-8">
						<div className="overflow-hidden rounded-lg border border-gray-200">
							<div className="flex items-center justify-between gap-4 border-b border-gray-100 px-5 py-4">
								<div>
									<p className="text-[13px] font-medium text-gray-800">
										{__('Require privacy consent', 'allcoach')}
									</p>
									<p className="mt-0.5 text-[12px] text-gray-400">
										{__(
											'Require visitors to accept the privacy policy before checkout and booking. The link points to your WordPress privacy policy page (Settings → Privacy).',
											'allcoach',
										)}
									</p>
								</div>
								<Switch
									checked={consentRequired}
									onCheckedChange={setConsentRequired}
									className="shrink-0 cursor-pointer data-[state=checked]:!bg-teal-600"
								/>
							</div>

							<div className="flex flex-col gap-4 px-5 py-4">
								<div className="flex flex-col gap-1.5">
									<Label htmlFor="ac-consent-text" className="text-[13px]">
										{__('Consent text', 'allcoach')}
									</Label>
									<Input
										id="ac-consent-text"
										value={consentText}
										onChange={(e) => setConsentText(e.target.value)}
										placeholder={__(
											'I agree to the {privacy_policy}.',
											'allcoach',
										)}
									/>
									<p className="text-[12px] text-gray-400">
										{__(
											'Use {privacy_policy} to insert a link to the privacy policy page.',
											'allcoach',
										)}
									</p>
								</div>

								<div className="flex flex-col gap-1.5">
									<Label htmlFor="ac-policy-version" className="text-[13px]">
										{__('Privacy policy version', 'allcoach')}
									</Label>
									<Input
										id="ac-policy-version"
										value={policyVersion}
										onChange={(e) => setPolicyVersion(e.target.value)}
										placeholder="1.0"
										className="max-w-[160px]"
									/>
									<p className="text-[12px] text-gray-400">
										{__(
											'Recorded with each consent. Bump this when your policy changes.',
											'allcoach',
										)}
									</p>
								</div>
							</div>
						</div>
					</div>

					{/* Danger zone — delete data on uninstall */}
					<div className="px-5 pb-6 md:px-8">
						<div className="overflow-hidden rounded-lg border border-red-200">
							<div className="flex items-center justify-between gap-4 px-5 py-4">
								<div>
									<p className="text-[13px] font-medium text-red-700">
										{__('Delete all data on uninstall', 'allcoach')}
									</p>
									<p className="mt-0.5 text-[12px] text-gray-400">
										{__(
											'When enabled, deleting the plugin permanently removes all AllCoach data — programs, orders, enrollments, bookings, activity data, client records and settings. Disabled by default so your data is kept if you deactivate or reinstall.',
											'allcoach',
										)}
									</p>
								</div>
								<Switch
									checked={deleteDataOnUninstall}
									onCheckedChange={setDeleteDataOnUninstall}
									className="shrink-0 cursor-pointer data-[state=checked]:!bg-red-600"
								/>
							</div>

							{deleteDataOnUninstall ? (
								<div className="flex items-center gap-2 border-t border-red-200 bg-red-50 px-5 py-3">
									<AlertTriangle className="size-4 shrink-0 text-red-600" />
									<p className="text-[12px] text-red-700">
										{__(
											'Warning: this cannot be undone. All data will be erased the moment the plugin is deleted from the Plugins screen.',
											'allcoach',
										)}
									</p>
								</div>
							) : null}
						</div>
					</div>

					{/* Footer */}
					<div className="flex justify-end gap-2 border-t border-gray-100 px-5 py-4 md:px-8">
						<Button
							type="button"
							size="sm"
							className="cursor-pointer text-[13px]"
							disabled={save.isPending}
							onClick={() => save.mutate()}
						>
							{save.isPending ? <Spinner className="size-3" /> : null}
							{__('Save', 'allcoach')}
						</Button>
					</div>
				</>
			)}
		</div>
	);
};

export default AdvancedSettings;
