import type { AnalyticsDashboard, AnalyticsKpi } from '@/admin/api/analytics';
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from '@/components/ui/select';
import { Skeleton } from '@/components/ui/skeleton';
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { __, sprintf } from '@wordpress/i18n';
import { ArrowDown, ArrowUp, Info } from 'lucide-react';
import { useEffect, useState } from 'react';
import { useAnalyticsPreferences } from './use-analytics-preferences';
import { formatChangePct, formatCurrency, formatNumber } from './utils';

type MetricKey = keyof AnalyticsDashboard['kpis'];

const METRICS: Record<
	MetricKey,
	{
		label: string;
		format: (kpi: AnalyticsKpi, currency: string) => string;
		/** Optional clarification shown via an info tooltip next to the value. */
		hint?: string;
	}
> = {
	revenue: {
		label: __('Net Revenue', 'allcoach'),
		format: (kpi, currency) => formatCurrency(kpi.value, kpi.currency ?? currency),
		hint: __('Paid orders minus refunds within the selected date range.', 'allcoach'),
	},
	avg_order_revenue: {
		label: __('Avg Order Revenue', 'allcoach'),
		format: (kpi, currency) => formatCurrency(kpi.value, kpi.currency ?? currency),
		hint: __('Net revenue divided by the number of paid orders.', 'allcoach'),
	},
	orders: {
		label: __('Orders', 'allcoach'),
		format: (kpi) => formatNumber(kpi.value),
	},
	clients: {
		label: __('Clients', 'allcoach'),
		format: (kpi) => formatNumber(kpi.value),
		hint: __('Distinct clients enrolled within the selected date range.', 'allcoach'),
	},
	enrollments: {
		label: __('Enrollments', 'allcoach'),
		format: (kpi) => formatNumber(kpi.value),
	},
	sessions: {
		label: __('Appointments', 'allcoach'),
		format: (kpi) => formatNumber(kpi.value),
		hint: __('Appointments scheduled within the selected date range.', 'allcoach'),
	},
};

const METRIC_KEYS = Object.keys(METRICS) as MetricKey[];
const DEFAULT_SLOTS: MetricKey[] = [
	'revenue',
	'avg_order_revenue',
	'clients',
	'sessions',
];

/** Metrics rendered as currency (their KPI carries a `currency`). */
const CURRENCY_METRICS: MetricKey[] = ['revenue', 'avg_order_revenue'];

function formatPrevious(key: MetricKey, kpi: AnalyticsKpi, currency: string) {
	return CURRENCY_METRICS.includes(key)
		? formatCurrency(kpi.previous, kpi.currency ?? currency)
		: formatNumber(kpi.previous);
}

function KpiCell({
	metric,
	onMetricChange,
	data,
}: {
	metric: MetricKey;
	onMetricChange: (m: MetricKey) => void;
	data: AnalyticsDashboard;
}) {
	const kpi = data.kpis[metric];
	const { text, direction } = formatChangePct(kpi.change_pct);
	const Arrow = direction === 'down' ? ArrowDown : ArrowUp;

	return (
		<div className="p-5">
			{/* Metric selector — pick which metric this slot shows. Picking one
			    already shown in another slot swaps the two, so a metric is
			    never shown twice. */}
			<Select value={metric} onValueChange={(v) => onMetricChange(v as MetricKey)}>
				<SelectTrigger className="h-auto w-fit gap-1 border-0 bg-transparent p-0 text-sm font-medium text-gray-600 shadow-none hover:text-gray-900 focus-visible:ring-0 dark:bg-transparent">
					<SelectValue />
				</SelectTrigger>
				<SelectContent align="start">
					{METRIC_KEYS.map((k) => (
						<SelectItem key={k} value={k}>
							{METRICS[k].label}
						</SelectItem>
					))}
				</SelectContent>
			</Select>

			<div className="mt-2 flex items-center gap-2">
				<span className="text-3xl font-bold tracking-tight text-gray-900">
					{METRICS[metric].format(kpi, data.currency)}
				</span>
				<span
					className={cn(
						'inline-flex items-center gap-0.5 text-xs font-semibold',
						direction === 'up' && 'text-emerald-600',
						direction === 'down' && 'text-red-500',
						direction === 'flat' && 'text-gray-400',
					)}
				>
					{direction !== 'flat' && <Arrow className="size-3" />}
					{text}
				</span>
				{METRICS[metric].hint && (
					<Tooltip>
						<TooltipTrigger asChild>
							<button
								type="button"
								aria-label={METRICS[metric].hint}
								className="text-gray-400 transition-colors hover:text-gray-600"
							>
								<Info className="size-3.5" />
							</button>
						</TooltipTrigger>
						<TooltipContent side="top" className="max-w-[220px]">
							{METRICS[metric].hint}
						</TooltipContent>
					</Tooltip>
				)}
			</div>

			<p className="mt-1 text-xs text-gray-500">
				{sprintf(
					/* translators: %s is the previous-period value. */
					__('vs. %s last period', 'allcoach'),
					formatPrevious(metric, kpi, data.currency),
				)}
			</p>
		</div>
	);
}

export default function KpiCards({ data }: { data: AnalyticsDashboard }) {
	const { preferences, loaded, savePreferences } = useAnalyticsPreferences();
	const [slots, setSlots] = useState<MetricKey[]>(DEFAULT_SLOTS);

	// Apply the server-stored slot picks once they've loaded.
	useEffect(() => {
		if (!loaded) return;
		const stored = preferences.kpi_slots;
		if (
			stored?.length === DEFAULT_SLOTS.length &&
			stored.every((k) => METRIC_KEYS.includes(k as MetricKey))
		) {
			setSlots(stored as MetricKey[]);
		}
	}, [loaded]);

	const setSlot = (index: number, metric: MetricKey) =>
		setSlots((prev) => {
			// A metric can only appear once — picking one already shown in
			// another slot swaps the two rather than duplicating it. (With
			// exactly as many metrics as slots, disabling the taken ones would
			// leave nothing left to pick — every slot always has something.)
			const takenAt = prev.indexOf(metric);
			const next = prev.map((m, i) => {
				if (i === index) return metric;
				if (i === takenAt) return prev[index];
				return m;
			});
			savePreferences({ kpi_slots: next });
			return next;
		});

	if (!loaded) {
		return (
			<div className="grid grid-cols-1 divide-y divide-gray-200 sm:grid-cols-2 sm:divide-x xl:grid-cols-4 xl:divide-y-0">
				{DEFAULT_SLOTS.map((key) => (
					<div key={key} className="p-5">
						<Skeleton className="h-4 w-20" />
						<Skeleton className="mt-3 h-8 w-24" />
						<Skeleton className="mt-2 h-3 w-28" />
					</div>
				))}
			</div>
		);
	}

	return (
		<div className="grid grid-cols-1 divide-y divide-gray-200 sm:grid-cols-2 sm:divide-x xl:grid-cols-4 xl:divide-y-0">
			{slots.map((metric, i) => (
				<KpiCell
					key={i}
					metric={metric}
					onMetricChange={(m) => setSlot(i, m)}
					data={data}
				/>
			))}
		</div>
	);
}
