import { Button } from '@/components/ui/button';
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
} from '@/components/ui/dialog';
import { cn } from '@/lib/utils';
import { __ } from '@wordpress/i18n';
import { CrownIcon, Lock } from 'lucide-react';

/** Opens the marketing/upgrade page in a new tab. */
export function openUpgrade(): void {
	const url = __ALLCOACH_ADMIN__.upgradeUrl || '#';
	window.open(url, '_blank', 'noopener,noreferrer');
}

/** Teal "Upgrade to Pro" call to action, reused in the filter bar and showcase card. */
export function UpgradeButton({
	className,
	size = 'sm',
}: {
	className?: string;
	size?: 'sm' | 'default';
}) {
	return (
		<Button
			size={size}
			onClick={openUpgrade}
			className={cn('bg-teal-600 text-white hover:bg-teal-700', className)}
		>
			<CrownIcon className="size-4" />
			{__('Upgrade to Pro', 'allcoach')}
		</Button>
	);
}

/**
 * The single centered showcase card (Everest-style "Unlock Advanced Analytics").
 * Rendered once, over the dimmed advanced section — not per control.
 */
export function UnlockAnalyticsCard({
	title = __('Unlock Advanced Analytics', 'allcoach'),
	description = __(
		'Get detailed breakdowns, custom date ranges, per-program insights and more with AllCoach Pro.',
		'allcoach',
	),
}: {
	title?: string;
	description?: string;
}) {
	return (
		<div className="pointer-events-auto w-[min(24rem,90%)] rounded-2xl border border-gray-200 bg-white p-7 text-center shadow-xl">
			<span className="mx-auto mb-4 flex size-12 items-center justify-center rounded-full bg-teal-50 text-teal-600 ring-1 ring-teal-200">
				<Lock className="size-5" />
			</span>
			<h3 className="text-lg font-semibold text-gray-900">{title}</h3>
			<p className="mx-auto mt-2 max-w-xs text-sm text-gray-500">
				{description}
			</p>
			<UpgradeButton className="mt-5" />
		</div>
	);
}

/**
 * Modal upsell shown when a locked control (Export, Print, filters) is clicked.
 * The built-in close ✕ comes from DialogContent.
 */
export function UpgradeDialog({
	open,
	onOpenChange,
	title,
	description,
}: {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	title: string;
	description: string;
}) {
	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogContent className="gap-1 sm:max-w-sm">
				<DialogHeader className="items-center gap-1 text-center sm:text-center">
					<span className="mx-auto mb-1 flex size-12 items-center justify-center rounded-full bg-teal-50 text-teal-600 ring-1 ring-teal-200">
						<Lock className="size-5" />
					</span>
					<DialogTitle className="text-xl">{title}</DialogTitle>
					<DialogDescription className="mx-auto max-w-sm text-center">
						{description}
					</DialogDescription>
				</DialogHeader>
				<div className="flex justify-center pt-1">
					<UpgradeButton />
				</div>
			</DialogContent>
		</Dialog>
	);
}
