export type ActivityField = {
	id: string;
	type: string;
	label?: string;
	question?: string;
	options?: Array<{ id: string; label: string }>;
	required?: boolean;
};

export function extractFieldsFromContent(
	content: Record<string, unknown> | Array<Record<string, unknown>>,
): ActivityField[] {
	const fields: ActivityField[] = [];
	const items = Array.isArray(content) ? content : [content];

	for (const node of items) {
		if (!node || typeof node !== 'object') continue;

		const nodeType = (node.type as string) || '';
		const attrs = (node.attrs as Record<string, unknown>) || {};

		if (
			[
				'shortAnswer',
				'longAnswer',
				'multipleChoice',
				'checkbox',
				'date',
				'fileUpload',
			].includes(nodeType)
		) {
			fields.push({
				id: (attrs.id as string) || '',
				type: nodeType,
				label: (attrs.label as string) || '',
				question: (attrs.question as string) || (attrs.label as string) || '',
				options: (attrs.options as Array<{ id: string; label: string }>) || [],
				required: (attrs.required as boolean) || false,
			});
		}

		if (node.content && Array.isArray(node.content)) {
			fields.push(...extractFieldsFromContent(node.content));
		}
	}

	return fields;
}

export function getFieldTypeLabel(type: string): string {
	const labels: Record<string, string> = {
		shortAnswer: __('Short answer', 'allcoach'),
		longAnswer: __('Long answer', 'allcoach'),
		multipleChoice: __('Multiple choice', 'allcoach'),
		checkbox: __('Checkbox', 'allcoach'),
		date: __('Date', 'allcoach'),
		fileUpload: __('File upload', 'allcoach'),
	};
	return labels[type] || type;
}

export function formatFieldValue(
	field: ActivityField,
	value: unknown,
): string | string[] {
	if (value === null || value === undefined) {
		return __('No answer provided', 'allcoach');
	}

	if (field.type === 'multipleChoice' && typeof value === 'string') {
		const option = field.options?.find((opt) => opt.id === value);
		return option?.label || String(value);
	}

	if (field.type === 'checkbox' && Array.isArray(value)) {
		return value
			.map((id) => {
				const option = field.options?.find((opt) => opt.id === id);
				return option?.label || String(id);
			})
			.filter(Boolean);
	}

	if (Array.isArray(value)) {
		return value.join(', ');
	}

	if (typeof value === 'object') {
		return JSON.stringify(value, null, 2);
	}

	return String(value);
}

